/// Format a single GateSpec into a human-readable string fragment.
fn gate_spec_fmt(g: &crate::dialect_expansion::GateSpec) -> String {
    // A threshold is a value on that mark's axis, so it prints as the Shavian
    // letter that value is, not as the ordinal number standing behind it: the
    // first value on the axis that meets the bar.
    let table = crate::catalog::ordinal_table(g.prim);
    let value = table
        .iter()
        .find(|v| v.ordinal() >= g.min_ord)
        .or_else(|| table.last());
    match value {
        Some(v) => format!("{}≥{}", g.prim, v.glyph()),
        None => format!("{}≥{}", g.prim, g.min_ord),
    }
}

/// Return the gate summary string for a dialect.
pub fn dialect_gates(u: u8) -> String {
    // Every dialect carries its gates as GateSpecs in the marks, and the summary
    // is printed from them. There is one notation, the marks, and this is it.
    if is_out_of_range(u) {
        return "Unknown gates".to_string();
    }
    // 8-11's real gates are the hand-crafted ordinal thresholds in
    // dialect_gates_pass, not all_dialects()[u]'s g1/g2/g3 — that array
    // holds a second, unrelated dialect family colliding with these same
    // three numbers (see the SINGLE SOURCE OF TRUTH section below). 0-7
    // read all_dialects() directly in dialect_gates_pass too, so no
    // collision is possible there and the existing path is already right.
    match u {
        8 => return "G1:⊥≥𐑖  G2:⊙≥⊙  G3:⊡≥𐑭  [seq]  T:dynamic".to_string(),
        9 => return "G1:∈≥𐑲  G2:⊙≥⊙  G3:⊡≥𐑭  [seq]  T:dynamic".to_string(),
        10 => return "G1:⊙≥𐑢  G2:⊙≥⊙  G3:⊙≥𐑣  [seq]  T:dynamic".to_string(),
        11 => return "G1:⊙≥𐑢  G2:⊙≥⊙  G3:⊙≥𐑣  [seq]  T:dynamic (gapped)".to_string(),
        _ => {}
    }
    let unis = all_dialects();
    let uni = &unis[u as usize];
    format!(
        "G1:{}  G2:{}  G3:{}  [{}]  T:{}",
        gate_spec_fmt(&uni.g1),
        gate_spec_fmt(&uni.g2),
        gate_spec_fmt(&uni.g3),
        if uni.gate_ordering { "seq" } else { "par" },
        if uni.t_entries.is_empty() { "none" } else { "dynamic" }
    )
}

/// Return O_∞ fraction description for a dialect.
pub fn dialect_o_inf(u: u8) -> &'static str {
    match u {
        0 => "~8%",  1 => "~30%", 2 => "~3.3%", 3 => "~8%",
        4 => "~8%",  5 => "~3%",  6 => "~8%",   7 => "~8%", 8 => "20%", 9 => "13.3%",
        10 => "16%", 11 => "16%",
        _ if is_expansion(u) => "compute",
        _ => "?",
    }
}

